-- =====================================================================
-- Reemplaza TODOS los partidos por los de la Federación Aragonesa (temporada 2026-27)
-- Origen: BD federativa local (ffv_statsbomb_20261102_200113.dump, tabla match),
-- 15 equipos del club 100718. Total partidos: 168 (65 finalizados).
-- Se borran partidos y eventos de calendario tipo Partido del club escuela-huesca;
-- los informes de partido (match_reports) NO se tocan. Finished = jugado con acta cerrada o resultado distinto de 0-0.
-- =====================================================================

BEGIN;
DELETE FROM eventos_calendario WHERE club_id = 'escuela-huesca' AND type = 'Partido';
DELETE FROM partidos;



COMMIT;
